package x86

// Expected arithmetic uses host u128/i64 and independent source-element loops.
// Every recipe comes from production assembly/physical decode of real forms.
const x86Avx512IntegerRecipeTests = `
fn avx_integer(text:&str,st:&State)->Transition{s::evaluate(&memory_recipe(text),st).unwrap_or_else(|e|panic!("{text}: {e:?}"))}
fn pack_int_lanes(values:&[u64],w:u8)->Vec<u64>{let mut v=vec![0;values.len()*usize::from(w)/64];let mask=if w==64{u64::MAX}else{(1u64<<w)-1};for(i,&x)in values.iter().enumerate(){v[i*usize::from(w)/64]|=(x&mask)<<((i*usize::from(w))%64);}v}
fn int_lane(t:&Transition,n:u16,lane:usize,w:u8)->u64{let value=vector_result(t,n,(lane*usize::from(w)/64)as u16)>>((lane*usize::from(w))%64);if w==64{value}else{value&((1u64<<w)-1)}}
fn vnni_expected(acc:u32,a:u32,b:u32,words:bool,saturate:bool)->u32{let mut total=i64::from(acc as i32);if words{for k in 0..2{total+=i64::from((a>>(16*k))as u16 as i16)*i64::from((b>>(16*k))as u16 as i16)}}else{for k in 0..4{total+=i64::from((a>>(8*k))as u8)*i64::from((b>>(8*k))as u8 as i8)}}if saturate{total.clamp(i64::from(i32::MIN),i64::from(i32::MAX))as i32 as u32}else{total as u32}}
#[test]fn actual_ifma_52bit_product_parts_accumulator_wrap_and_aliases(){
 let a=[u64::MAX,0x0010000000000001,0x000fffffffffffff,0x123456789abcdef0,0,1,0xffff000000000001,0x0008000000000000];let b=[u64::MAX,u64::MAX,0x000fffffffffffff,0x9876543210fedcba,9,u64::MAX,0x000fffffffffffff,0x0008000000000000];let acc=[u64::MAX,0,9,0xfffffffffffffff0,1,1,1,0xabcdef1234567890];
 for (vl,regname)in[(128,"xmm"),(256,"ymm"),(512,"zmm")]{for high in [false,true]{for alias in [0,1,2]{let mut st=State::default();vector(&mut st,0,&acc);vector(&mut st,1,&a);vector(&mut st,2,&b);let (ar,br)=if alias==1{(0,2)}else if alias==2{(1,0)}else{(1,2)};let av=if alias==1{acc}else{a};let bv=if alias==2{acc}else{b};let stem=if high{"vpmadd52huq"}else{"vpmadd52luq"};let text=format!("{stem} {regname}0, {regname}{ar}, {regname}{br}");let enc=assemble_at(&text,0).unwrap();for mode in[Mode::Mode16,Mode::Mode32,Mode::Mode64]{let d=decode(enc[0].bytes(),mode).unwrap();let r=d.semantic_recipe(0);assert_eq!(r.support,Support::Full);r.validate().unwrap();let t=s::evaluate(&r,&st).unwrap();for i in 0..vl/64{let product=u128::from(av[i]&0xfffffffffffff)*u128::from(bv[i]&0xfffffffffffff);let part=(if high{product>>52}else{product})as u64&0xfffffffffffff;assert_eq!(vector_result(&t,0,i as u16),acc[i].wrapping_add(part),"{text} lane{i}");}for i in vl/64..8{assert_eq!(vector_result(&t,0,i as u16),0)}}}}}
}
#[test]fn actual_vnni_signed_unsigned_dot_wrap_and_saturation_once(){
 let a=[0xffffffff,0x80808080,0x80008000,0x7fff7fff,0x01020304,0x0000ffff,0,0xffffffff];let b=[0x80808080,0x7f7f7f7f,0x80008000,0x7fff7fff,0xff80017f,0xffff0001,0xffffffff,0xffffffff];let acc=[0x80000000,0x7fffffff,0xffffffff,0x7fffffff,9,0x80000000,7,0x7fffffff];
 for(vl,regname)in[(128,"xmm"),(256,"ymm"),(512,"zmm")]{for(stem,words,sat)in[("vpdpbusd",false,false),("vpdpbusds",false,true),("vpdpwssd",true,false),("vpdpwssds",true,true)]{for alias in[0,1,2]{let mut st=State::default();let aa:Vec<_>=(0..vl/32).map(|i|a[i%8]).collect();let bb:Vec<_>=(0..vl/32).map(|i|b[i%8]).collect();let dd:Vec<_>=(0..vl/32).map(|i|acc[i%8]).collect();vector(&mut st,0,&pack_int_lanes(&dd,32));vector(&mut st,1,&pack_int_lanes(&aa,32));vector(&mut st,2,&pack_int_lanes(&bb,32));let(ar,br)=if alias==1{(0,2)}else if alias==2{(1,0)}else{(1,2)};let t=avx_integer(&format!("{stem} {regname}0, {regname}{ar}, {regname}{br}"),&st);for i in 0..vl/32{assert_eq!(int_lane(&t,0,i,32),u64::from(vnni_expected(dd[i]as u32,if alias==1{dd[i]}else{aa[i]}as u32,if alias==2{dd[i]}else{bb[i]}as u32,words,sat)));}for i in vl/64..8{assert_eq!(vector_result(&t,0,i as u16),0)}}}}
}
#[test]fn actual_conflict_all_prior_elements_including_masked_ones_and_aliases(){
 for(w,suffix)in[(32,"d"),(64,"q")]{for(vl,regname)in[(128,"xmm"),(256,"ymm"),(512,"zmm")]{let n=vl/usize::from(w);let values:Vec<_>=(0..n).map(|i|if i%3==0{9}else{(i%2)as u64}).collect();let mut st=State::default();vector(&mut st,0,&pack_int_lanes(&values,w));vector(&mut st,1,&pack_int_lanes(&values,w));st.reg("x86.mask",1,1u64<<(n-1));for alias in[false,true]{let t=avx_integer(&format!("vpconflict{suffix} {regname}0 {{k1}}{{z}}, {regname}{}",if alias{0}else{1}),&st);for i in 0..n{let expected=if i==n-1{(0..i).filter(|&j|values[j]==values[i]).fold(0,|m,j|m|1u64<<j)}else{0};assert_eq!(int_lane(&t,0,i,w),expected);}for i in vl/64..8{assert_eq!(vector_result(&t,0,i as u16),0)}}}}
}
#[test]fn actual_population_leading_zero_counts_and_cd_mask_broadcasts(){
 for(w,suffix)in[(8,"b"),(16,"w"),(32,"d"),(64,"q")]{for(vl,regname)in[(128,"xmm"),(256,"ymm"),(512,"zmm")]{let n=vl/usize::from(w);let values:Vec<_>=(0..n).map(|i|[0,u64::MAX,1,0x8000000080000000,0x5555555555555555][i%5]).collect();let mut st=State::default();vector(&mut st,0,&pack_int_lanes(&values,w));st.reg("x86.mask",1,0xaaaaaaaaaaaaaaaa);let t=avx_integer(&format!("vpopcnt{suffix} {regname}0 {{k1}}{{z}}, {regname}0"),&st);for i in 0..n{let v=values[i]&if w==64{u64::MAX}else{(1u64<<w)-1};assert_eq!(int_lane(&t,0,i,w),if i%2==1{u64::from(v.count_ones())}else{0});}if w>=32{let t=avx_integer(&format!("vplzcnt{suffix} {regname}0, {regname}0"),&st);for i in 0..n{let v=values[i]&if w==64{u64::MAX}else{(1u64<<w)-1};assert_eq!(int_lane(&t,0,i,w),u64::from(v.leading_zeros())-u64::from(64-w));}}}}
 let mut st=State::default();st.reg("x86.mask",3,0xfedcba987654abcd);for(vl,regname)in[(128,"xmm"),(256,"ymm"),(512,"zmm")]{for(w,stem,expected)in[(64,"vpbroadcastmb2q",0xcd),(32,"vpbroadcastmw2d",0xabcd)]{let t=avx_integer(&format!("{stem} {regname}0, k3"),&st);for i in 0..vl/usize::from(w){assert_eq!(int_lane(&t,0,i,w),expected)}for i in vl/64..8{assert_eq!(vector_result(&t,0,i as u16),0)}}}
}

struct NoIntegerVectorReads<'a>(&'a AccessState);
impl Machine for NoIntegerVectorReads<'_>{
 fn read_register(&self,r:s::Register)->Value{assert!(r.bank!="x86.vector64"||r.index<8,"inactive vector source was read: {r:?}");self.0.read_register(r)}
 fn read_memory(&self,a:u64,w:u8,e:s::Endian)->Result<Value,EvalError>{self.0.read_memory(a,w,e)}
 fn read_wide_memory(&self,a:u64,w:u16,e:s::Endian)->Result<Vec<Value>,EvalError>{self.0.read_wide_memory(a,w,e)}
}
fn integer_broadcast(text:&str)->s::Recipe{let enc=assemble_at(text,0).unwrap();let mut bytes=enc[0].bytes().to_vec();bytes[3]|=16;let d=decode(&bytes,Mode::Mode64).unwrap();let r=d.semantic_recipe(0);assert_eq!(r.support,Support::Full);r.validate().unwrap();r}
#[test]fn actual_ifma_vnni_counts_masked_memory_guards_and_broadcasts(){
 let mut st=AccessState::new();st.unknown_address=true;st.state.reg("x86.mask",1,0);
 for text in["vpmadd52huq zmm0 {k1}{z}, zmm1, zmmword ptr [rax]","vpdpbusds zmm0 {k1}{z}, zmm1, zmmword ptr [rax]","vpdpwssds zmm0 {k1}{z}, zmm1, zmmword ptr [rax]","vplzcntd zmm0 {k1}{z}, zmmword ptr [rax]","vpopcntq zmm0 {k1}{z}, zmmword ptr [rax]","vpopcntb zmm0 {k1}{z}, zmmword ptr [rax]","vp4dpwssds zmm0 {k1}{z}, zmm7, xmmword ptr [rax]"]{let r=memory_recipe(text);let t=s::evaluate(&r,&NoIntegerVectorReads(&st)).unwrap();for i in 0..8{assert_eq!(vector_result(&t,0,i),0)}}assert_eq!(st.address_reads.get(),0);assert!(st.reads.borrow().is_empty());
 st.unknown_address=false;st.state.x(0,0x4000);st.state.reg("x86.mask",1,0x81);vector(&mut st.state,0,&[9;8]);vector(&mut st.state,1,&[0xfffffffffffff;8]);st.state.mem.insert(0x4000,0xfffffffffffff);st.state.mem.insert(0x4038,2);let t=memory_eval("vpmadd52huq zmm0 {k1}{z}, zmm1, zmmword ptr [rax]",&st);assert_eq!(*st.reads.borrow(),vec![(0x4000,64),(0x4038,64)]);assert_eq!(vector_result(&t,0,0),9+0xffffffffffffe);assert_eq!(vector_result(&t,0,7),10);
 st.reads.borrow_mut().clear();let t=s::evaluate(&integer_broadcast("vpmadd52luq zmm0 {k1}{z}, zmm1, zmmword ptr [rax]"),&st).unwrap();assert_eq!(*st.reads.borrow(),vec![(0x4000,64)]);assert_eq!(vector_result(&t,0,0),10);assert_eq!(vector_result(&t,0,7),10);
 st.reads.borrow_mut().clear();st.state.reg("x86.mask",1,0x8001);vector(&mut st.state,0,&[0;8]);vector(&mut st.state,1,&[0x0101010101010101;8]);st.state.mem.insert(0x4000,0x02020202);st.state.mem.insert(0x403c,0x80808080);let t=memory_eval("vpdpbusd zmm0 {k1}{z}, zmm1, zmmword ptr [rax]",&st);assert_eq!(*st.reads.borrow(),vec![(0x4000,32),(0x403c,32)]);assert_eq!(int_lane(&t,0,0,32),8);assert_eq!(int_lane(&t,0,15,32),(-512i32)as u32 as u64);
 st.reads.borrow_mut().clear();let t=s::evaluate(&integer_broadcast("vpdpbusds zmm0 {k1}{z}, zmm1, zmmword ptr [rax]"),&st).unwrap();assert_eq!(*st.reads.borrow(),vec![(0x4000,32)]);assert_eq!(int_lane(&t,0,15,32),8);
 st.reads.borrow_mut().clear();st.state.mem.insert(0x4000,0xffff);st.state.mem.insert(0x403c,0);let t=memory_eval("vplzcntd zmm0 {k1}{z}, zmmword ptr [rax]",&st);assert_eq!(*st.reads.borrow(),vec![(0x4000,32),(0x403c,32)]);assert_eq!(int_lane(&t,0,0,32),16);assert_eq!(int_lane(&t,0,15,32),32);
 st.reads.borrow_mut().clear();let t=s::evaluate(&integer_broadcast("vpopcntd zmm0 {k1}{z}, zmmword ptr [rax]"),&st).unwrap();assert_eq!(*st.reads.borrow(),vec![(0x4000,32)]);assert_eq!(int_lane(&t,0,15,32),16);
 st.state.reg("x86.mask",1,3);st.state.mem.remove(&0x4004);assert_eq!(s::evaluate(&memory_recipe("vpdpbusd zmm0 {k1}{z}, zmm1, zmmword ptr [rax]"),&st),Err(EvalError::Memory));
}
#[test]fn actual_conflict_nf_full_access_and_broadcast_even_at_empty_mask(){
 let mut st=AccessState::new();st.state.x(0,0x5000);for i in 0..8{st.state.mem.insert(0x5000+i*8,0x0000000700000007);}st.state.reg("x86.mask",1,0);let t=memory_eval("vpconflictd zmm0 {k1}{z}, zmmword ptr [rax]",&st);assert_eq!(*st.reads.borrow(),vec![(0x5000,512)]);for i in 0..8{assert_eq!(vector_result(&t,0,i),0)}
 st.reads.borrow_mut().clear();st.state.mem.remove(&0x5008);assert_eq!(s::evaluate(&memory_recipe("vpconflictd zmm0 {k1}{z}, zmmword ptr [rax]"),&st),Err(EvalError::Memory));assert_eq!(*st.reads.borrow(),vec![(0x5000,512)]);
 st.reads.borrow_mut().clear();st.state.mem.insert(0x5000,7);let t=s::evaluate(&integer_broadcast("vpconflictd zmm0 {k1}{z}, zmmword ptr [rax]"),&st).unwrap();assert_eq!(*st.reads.borrow(),vec![(0x5000,32)]);for i in 0..8{assert_eq!(vector_result(&t,0,i),0)}
 st.state.reg("x86.mask",1,0x8000);st.reads.borrow_mut().clear();let t=s::evaluate(&integer_broadcast("vpconflictd zmm0 {k1}{z}, zmmword ptr [rax]"),&st).unwrap();assert_eq!(int_lane(&t,0,15,32),0x7fff);assert_eq!(*st.reads.borrow(),vec![(0x5000,32)]);
 // Output lane0 is constant, and empty masks on register forms need no
 // unavailable vector values. Memory forms above still retain their NF read.
 st.state.reg("x86.mask",1,1);let t=s::evaluate(&memory_recipe("vpconflictd zmm0 {k1}{z}, zmm1"),&NoIntegerVectorReads(&st)).unwrap();for i in 0..8{assert_eq!(vector_result(&t,0,i),0)}
}
#[test]fn actual_avx512_integer_every_vector_and_element_width_accesses_only_active_memory(){
 for(vl,regname,memname)in[(128,"xmm","xmmword"),(256,"ymm","ymmword"),(512,"zmm","zmmword")]{for(stem,w,source,input,expected)in[("vpmadd52luq",64,1,7,7),("vpdpbusd",32,0x0101010101010101,0x02020202,8),("vpdpwssd",32,0x0001000100010001,0x00020002,4),("vplzcntd",32,0,1,31),("vplzcntq",64,0,1,63),("vpopcntb",8,0,0xff,8),("vpopcntw",16,0,0xffff,16),("vpopcntd",32,0,0xffffffff,32),("vpopcntq",64,0,u64::MAX,64)]{
  let n=vl/u16::from(w);let mut st=AccessState::new();st.state.x(0,0x7000);st.state.reg("x86.mask",1,1|(1u64<<(n-1)));vector(&mut st.state,1,&[source;8]);let last=0x7000+u64::from((n-1)*u16::from(w)/8);st.state.mem.insert(0x7000,input);st.state.mem.insert(last,input);let operands=if matches!(stem,"vpmadd52luq"|"vpdpbusd"|"vpdpwssd"){format!("{regname}1, ")}else{String::new()};let t=memory_eval(&format!("{stem} {regname}0 {{k1}}{{z}}, {operands}{memname} ptr [rax]"),&st);assert_eq!(*st.reads.borrow(),vec![(0x7000,u16::from(w)),(last,u16::from(w))],"{stem} {vl}");for i in 0..n{assert_eq!(int_lane(&t,0,usize::from(i),w),if i==0||i==n-1{expected}else{0},"{stem} {vl} lane{i}");}
 }}
 for(vl,regname,memname)in[(128,"xmm","xmmword"),(256,"ymm","ymmword"),(512,"zmm","zmmword")]{for(w,suffix)in[(32,"d"),(64,"q")]{let n=vl/u16::from(w);let mut st=AccessState::new();st.state.x(0,0x8000);st.state.reg("x86.mask",1,1u64<<(n-1));for chunk in 0..vl/64{st.state.mem.insert(0x8000+u64::from(chunk*8),if w==32{0x0000000700000007}else{7});}let t=memory_eval(&format!("vpconflict{suffix} {regname}0 {{k1}}{{z}}, {memname} ptr [rax]"),&st);assert_eq!(*st.reads.borrow(),vec![(0x8000,vl)]);assert_eq!(int_lane(&t,0,usize::from(n-1),w),(1u64<<(n-1))-1);}}
}
#[test]fn actual_4vnniw_group_selection_sequential_saturation_and_single_guarded_access(){
 let mut st=AccessState::new();st.state.x(0,0x6000);st.state.mem.insert(0x6000,0x7fff7fff7fff7fff);st.state.mem.insert(0x6008,0);vector(&mut st.state,0,&[0x7fffffff7fffffff;8]);vector(&mut st.state,4,&[0x7fff7fff7fff7fff;8]);vector(&mut st.state,5,&[0x8000800080008000;8]);vector(&mut st.state,6,&[0;8]);vector(&mut st.state,7,&[0;8]);
 for(text,expected)in[("vp4dpwssd zmm0, zmm7, xmmword ptr [rax]",0x7fff0001),("vp4dpwssds zmm0, zmm7, xmmword ptr [rax]",65535)]{st.reads.borrow_mut().clear();let t=memory_eval(text,&st);assert_eq!(*st.reads.borrow(),vec![(0x6000,128)]);for i in 0..16{assert_eq!(int_lane(&t,0,i,32),expected)}}
 // A source-block member can also be the accumulator/destination; each lane
 // consumes the incoming group before any architectural write occurs.
 let t=memory_eval("vp4dpwssds zmm4, zmm5, xmmword ptr [rax]",&st);let mut expected=0x7fff7fffi32 as i64;for(a,b)in[(0x7fff7fffu32,0x7fff7fff),(0x80008000,0x7fff7fff),(0,0),(0,0)]{expected=i64::from(vnni_expected(expected as u32,a,b,true,true)as i32)}for i in 0..16{assert_eq!(int_lane(&t,4,i,32),expected as u32 as u64)}
 st.state.reg("x86.mask",1,0x8001);st.reads.borrow_mut().clear();let t=memory_eval("vp4dpwssds zmm0 {k1}{z}, zmm7, xmmword ptr [rax]",&st);assert_eq!(*st.reads.borrow(),vec![(0x6000,128)]);assert_eq!(int_lane(&t,0,0,32),65535);assert_eq!(int_lane(&t,0,15,32),65535);for i in 1..15{assert_eq!(int_lane(&t,0,i,32),0)}
}
fn avx_integer_family(name:&str)->bool{matches!(name,"VPMADD52LUQ"|"VPMADD52HUQ"|"VPDPBUSD"|"VPDPBUSDS"|"VPDPWSSD"|"VPDPWSSDS"|"VPCONFLICTD"|"VPCONFLICTQ"|"VPLZCNTD"|"VPLZCNTQ"|"VPBROADCASTMB2Q"|"VPBROADCASTMW2D"|"VPOPCNTB"|"VPOPCNTW"|"VPOPCNTD"|"VPOPCNTQ"|"VP4DPWSSD"|"VP4DPWSSDS")}
#[test]fn actual_avx512_integer_merge_masks_preserve_inactive_elements_and_clear_upper(){
 let mut st=State::default();let old=[0xfedcba9876543210;8];vector(&mut st,0,&old);vector(&mut st,1,&[0x0001000100010001;8]);vector(&mut st,2,&[0x0002000200020002;8]);st.reg("x86.mask",1,0xaaaaaaaaaaaaaaaa);
 for(vl,regname)in[(128,"xmm"),(256,"ymm"),(512,"zmm")]{for(stem,w,three)in[("vpmadd52luq",64,true),("vpmadd52huq",64,true),("vpdpbusd",32,true),("vpdpbusds",32,true),("vpdpwssd",32,true),("vpdpwssds",32,true),("vpconflictd",32,false),("vpconflictq",64,false),("vplzcntd",32,false),("vplzcntq",64,false),("vpopcntb",8,false),("vpopcntw",16,false),("vpopcntd",32,false),("vpopcntq",64,false)]{let src=if three{format!("{regname}1, {regname}2")}else{format!("{regname}1")};let plain=avx_integer(&format!("{stem} {regname}0, {src}"),&st);for zero in [false,true]{let actual=avx_integer(&format!("{stem} {regname}0 {{k1}}{}, {src}",if zero{"{z}"}else{""}),&st);for lane in 0..vl/usize::from(w){let mask=if w==64{u64::MAX}else{(1u64<<w)-1};let prior=old[lane*usize::from(w)/64]>>((lane*usize::from(w))%64)&mask;assert_eq!(int_lane(&actual,0,lane,w),if lane%2==1{int_lane(&plain,0,lane,w)}else if zero{0}else{prior},"{stem} {regname} lane{lane} zero{zero}");}for chunk in vl/64..8{assert_eq!(vector_result(&actual,0,chunk as u16),0)}}}}
}
#[test]fn actual_avx512_integer_catalog_forms_modes_and_prefix_qualifications(){
 let mut forms=0;for i in 0..encoding_count(){let e=encoding(i).unwrap();if !avx_integer_family(e.mnemonic)||e.id.starts_with("XED-INTEGER/"){continue}forms+=1;for mode in[Mode::Mode16,Mode::Mode32,Mode::Mode64]{if !encoding_supports_mode(i,mode){continue}let mut bytes=[0;15];let n=encode_representative(i,mode,&mut bytes).unwrap();let d=decode(&bytes[..n],mode).unwrap();let r=d.semantic_recipe(0x1000);assert_eq!(r.support,Support::Full,"{} {mode:?}",e.form_id);r.validate().unwrap();if bytes[5]>>6==3{let mut invalid=bytes;invalid[3]|=16;if let Ok(d)=decode(&invalid[..n],mode){assert!(matches!(d.semantic_recipe(0).support,Support::Unsupported(_)),"reserved register-b bit: {}",e.form_id)}}}}
 assert_eq!(forms,92);
 for text in["vpmadd52luq xmm0 {k1}, xmm1, xmm2","vpdpbusd zmm0 {k1}, zmm1, zmm2","vpopcntq ymm0 {k1}, ymm1"]{let enc=assemble_at(text,0).unwrap();let mut bytes=enc[0].bytes().to_vec();bytes[3]=(bytes[3]&!7)|0x80;if let Ok(d)=decode(&bytes,Mode::Mode64){assert!(matches!(d.semantic_recipe(0).support,Support::Unsupported(_)),"zeroing without mask: {text}")}}
}
`
